import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const group = new Group();

  // --- Plane (sprite) ---
  const aspect = 512 / 320; // atlas region aspect ratio
  const planeGeom = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(planeGeom, material);
  group.add(mesh);

  // Load texture asynchronously; material updates when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = texture(tex);
      material.needsUpdate = true;
    });
  }

  // --- Text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: (config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2'),
      align: 'center',
      maxWidthPx: 0,
      letterSpacingPx: 0,
    });
    // Position text slightly in front of the plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    group.add(txt);
  }

  // --- Event handlers placeholder ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    planeGeom.dispose();
    // Dispose texture if it was assigned
    if (material.map && material.map.value) {
      material.map.value.dispose();
    }
    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return group;
}
